import time

from requests.exceptions import ConnectionError, ReadTimeout

from taf.gnb.oam.coam.vdu.exceptions import ParameterNotProvided, ApiException

DEFAULT_REQUEST_TIMEOUT = 30
DEFAULT_ERROR_BACKOFF = 10

OPERATION_TYPES = {
    "operation_id": {
        "arg_name": "operation_id",
        "extract_status": lambda x: x["status"],
        "timeout_kw": {"timeout": DEFAULT_REQUEST_TIMEOUT}
    },
    "action_id": {
        "arg_name": "action_id",
        "extract_status": lambda x: x.status,
        "timeout_kw": {"_request_timeout": DEFAULT_REQUEST_TIMEOUT}
    },
    "just_id": {
        "arg_name": "just_id",
        "extract_status": lambda x: x["isCompleted"],
        "timeout_kw": {"timeout": DEFAULT_REQUEST_TIMEOUT}
    },
    "monitor_id": {
        "arg_name": "monitor_id",
        "extract_status": lambda x: x["status"],
        "timeout_kw": {"timeout": DEFAULT_REQUEST_TIMEOUT},
    },
}


def poll_status(instance, method_name, timeout, polling_interval=5, operation_id=None, action_id=None, just_id=None,  # noqa: C901
                monitor_id=None, teardown_method_name=None, **kwargs):
    """
    Polls the status of an operation until it completes or times out

    :param instance: instance of the class that contains the method to be called
    :param method_name: name of the method to be called to get status of the operation
    :param timeout: maximum time to wait for the operation to complete
    :param polling_interval: (optional) time to wait between polling attempts, defaults to 5 seconds
    :param operation_id: (optional) ID of the operation to be polled, defaults to None.
                         One of: operation_id, action_id, just_id or monitor_id needs to be set
    :param action_id: (optional) ID of the action to be polled, defaults to None.
                      One of: operation_id, action_id, just_id or monitor_id needs to be set
    :param just_id: (optional) ID of the object to be polled. Use when key name is just 'id'. defaults to None.
                    One of: operation_id, action_id, just_id or monitor_id needs to be set
    :param monitor_id: (optional) ID of the monitor to be polled, defaults to None.
                       One of: operation_id, action_id, just_id or monitor_id needs to be set
    :param teardown_method_name: (optional) name of the method to be called in case of operation failure,
                                 defaults to None
    :return: operation info
    :raises TimeoutError: if the operation does not complete within the specified timeout
    :raises RuntimeError: if the operation fails
    """
    ids = {"operation_id": operation_id,
           "action_id": action_id,
           "just_id": just_id,
           "monitor_id": monitor_id}
    target_id = operation_id or action_id or just_id or monitor_id

    stop_time = time.time() + timeout

    while time.time() < stop_time:
        try:
            status, operation_info = _fetch_operation_status(instance=instance,
                                                             method_name=method_name,
                                                             ids=ids,
                                                             **kwargs)

            if status in ['failure', 'failed']:
                _teardown_and_raise(instance=instance,
                                    method_name=teardown_method_name,
                                    ids=ids,
                                    exception=RuntimeError(f"Operation {target_id} failed. Operation info: {operation_info}"),)

            if status in ['success', 'succeeded', True]:
                return operation_info

            time.sleep(polling_interval)

        except (ApiException, ConnectionError, ReadTimeout):
            time.sleep(DEFAULT_ERROR_BACKOFF if DEFAULT_ERROR_BACKOFF < timeout else polling_interval)

    _teardown_and_raise(instance=instance,
                        method_name=teardown_method_name,
                        ids=ids,
                        exception=TimeoutError(f"Operation {target_id} did not complete within {timeout} seconds"))


def _teardown_and_raise(instance, method_name, exception, ids):
    """Call teardown method and raise the given exception."""
    if method_name:
        teardown_method = getattr(instance, method_name)

        for key, config in OPERATION_TYPES.items():
            value = ids.get(key)
            if value is not None:
                teardown_method(**{config["arg_name"]: value}, **config["timeout_kw"])
                break

    raise exception

def _fetch_operation_status(instance, method_name, ids, **kwargs):
    """Fetch the status of an operation, handling different ID field names."""
    method = getattr(instance, method_name)

    for key, config in OPERATION_TYPES.items():
        value = ids.get(key)
        if value is not None:
            info = method(**{config["arg_name"]: value}, **config["timeout_kw"], **kwargs)
            return config["extract_status"](info), info

    raise ParameterNotProvided("One of: operation_id, action_id, just_id or monitor_id must be set")
